groups',NULL,'Clerical & administrative',NULL,NULL,NULL,'[\"Department Physician Coordinator\", \"Front Desk Associate\", \"Billing\", \"Clerical\"]',NULL,0,1,3,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(79,'industries',NULL,'Healthcare','The widest range of nurse and clinical staffing','Our nursing specialties and assignment lengths are fully customizable to fit your facility’s needs — from short-term coverage to permanent hires and interim leadership.','healthcare','[\"Nurse staffing services\", \"Travel nurse staffing\", \"Interim nurse leadership\", \"Physician staffing services\", \"Permanent placement\", \"Allied health staffing\", \"Permanent physician placement\", \"Temporary physician staffing\"]',NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(80,'industries',NULL,'Pharmaceuticals','Talent for a regulated, fast-moving industry','Pharmaceutical and life sciences companies face significant operational and regulatory challenges, constant pressure to innovate, eroding patent protection and fierce competition. We help them acquire and manage the talent they need to differentiate and grow.','pharma','[\"Administrative / clerical\", \"Research & development\", \"Marketing & communications\", \"Regulatory\", \"Accounting / finance\", \"Information technology\", \"Nursing\", \"HR / legal\", \"Quality assurance\", \"Chemistry\", \"Biochemistry\", \"Supply chain, procurement & logistics\", \"Scientific packaging & labels\", \"Clinical data\", \"Healthcare compliance & privacy\"]',NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(81,'industries',NULL,'Information Technology','Specialist recruiters from the industry','Information technology moves fast. Our recruiters come from the industry and bring deep domain expertise, helping companies acquire the talent to adapt, meet everyday challenges and capitalize on new opportunities.','it','[\"Project management\", \"Strategy & operations\", \"Testing & quality assurance\", \"Data warehousing\", \"Regulatory engineering\", \"IT training\", \"Research & development\", \"Sourcing & inventory management\", \"Customer service / call center\", \"Marketing & communications\", \"Accounting / finance\", \"HR / legal\"]',NULL,0,1,2,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(82,'faqs_employers',NULL,'What staffing models do you offer?',NULL,'Full-time, part-time, contract, temp-to-hire and urgent placements, plus permanent placement and interim nurse leadership. Assignments range from a few weeks to several months.',NULL,NULL,NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(83,'faqs_employers',NULL,'How do you vet candidates?',NULL,'Every professional in our network is pre-screened and matched to your requirements for skills, cultural fit and commitment before they are presented.',NULL,NULL,NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(84,'faqs_employers',NULL,'Can a contract clinician convert to a permanent hire?',NULL,'Yes. Our temp-to-hire model lets you evaluate a professional on the job before making a permanent offer.',NULL,NULL,NULL,0,1,2,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(85,'faqs_employers',NULL,'Do you staff roles outside healthcare?',NULL,'Yes. We also recruit for pharmaceutical and life sciences companies and for information technology teams.',NULL,NULL,NULL,0,1,3,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(86,'faqs_professionals',NULL,'How do I apply?',NULL,'Choose \"I’m looking for work\" on the form, share your details and attach your resume. A recruiter will contact you about roles that fit.',NULL,NULL,NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(87,'faqs_professionals',NULL,'What kinds of assignments are available?',NULL,'Travel, contract, temp-to-hire and permanent roles, with assignment lengths from a few weeks to several months.',NULL,NULL,NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(88,'faqs_professionals',NULL,'Will I have a dedicated recruiter?',NULL,'Yes. An experienced healthcare recruiter guides you from application through placement, and our management team steps in promptly if challenges arise.',NULL,NULL,NULL,0,1,2,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(89,'about_values',NULL,'Integrity',NULL,'We uphold transparency and honesty in every placement, building lasting trust with clients and candidates.',NULL,NULL,NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(90,'about_values',NULL,'People',NULL,'We put people first by empowering talent and nurturing strong, respectful relationships.',NULL,NULL,NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(91,'about_values',NULL,'Diversity',NULL,'We embrace diverse perspectives to deliver inclusive staffing that reflects the communities we serve.',NULL,NULL,NULL,0,1,2,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(92,'about_values',NULL,'Growth',NULL,'We drive continuous improvement and success for our clients, candidates and team.',NULL,NULL,NULL,0,1,3,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(93,'about_values',NULL,'Respect',NULL,'Every candidate and every client is treated as a partner.',NULL,NULL,NULL,0,1,4,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(94,'about_values',NULL,'National impact',NULL,'We connect skilled professionals across the nation to transform industries and improve lives.',NULL,NULL,NULL,0,1,5,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(95,'about_locations',NULL,'United States',NULL,'Headquartered in Kentucky, placing professionals with healthcare facilities nationwide.',NULL,NULL,NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(96,'about_locations',NULL,'India',NULL,'A strong presence that extends our global reach and sourcing capability.',NULL,NULL,NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(97,'contact_next_steps',NULL,NULL,NULL,'We review your request or application.',NULL,NULL,NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(98,'contact_next_steps',NULL,NULL,NULL,'A recruiter or account manager contacts you to understand your needs.',NULL,NULL,NULL,0,1,1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(99,'contact_next_steps',NULL,NULL,NULL,'We present matched candidates, or opportunities that fit you.',NULL,NULL,NULL,0,1,2,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(100,'footer_columns',NULL,'Services',NULL,NULL,NULL,'[\"Healthcare Staffing|/services#healthcare\", \"Pharmaceuticals|/services#pharma\", \"Information Technology|/services#it\", \"Staffing Models|/services#models\"]',NULL,0,1,0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(101,'footer_columns',NULL,'Professionals',NULL,NULL,NULL,'[\"Explore Opportunities|/#professionals\", \"Specialties|/services#specialties\", \"Apply Now|/contact\"]',NULL,0,1,1,'2026-10-13 16:04:46','2026-10-14 07:56:25'),(102,'footer_columns',NULL,'Employers',NULL,NULL,NULL,'[\"Request Talent|/contact\", \"How It Works|/#how-it-works\", \"Why Unite Systems|/about#why\"]',NULL,0,1,2,'2026-10-13 16:04:46','2026-10-14 07:56:25'),(103,'footer_columns',NULL,'Company',NULL,NULL,NULL,'[\"About Us|/about\", \"Testimonials|/#testimonials\", \"Contact Us|/contact\"]',NULL,0,1,3,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(104,'footer_columns',NULL,'Resources',NULL,NULL,NULL,'[\"Jobs|/jobs\", \"Privacy Policy|/privacy\"]',NULL,0,1,4,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(105,'home_humantech_professionals','HeartPulse','Nurses',NULL,NULL,NULL,NULL,NULL,0,1,0,'2026-10-14 06:02:28','2026-10-14 06:02:28'),(106,'home_humantech_professionals','FlaskConical','Allied & imaging',NULL,NULL,NULL,NULL,NULL,0,1,1,'2026-10-14 06:02:28','2026-10-14 06:02:28'),(107,'home_humantech_professionals','Identification','Health IT & admin',NULL,NULL,NULL,NULL,NULL,0,1,2,'2026-10-14 06:02:28','2026-10-14 06:02:28'),(108,'home_humantech_organizations','Building2','Hospitals',NULL,NULL,NULL,NULL,NULL,0,1,0,'2026-10-14 06:02:28','2026-10-14 06:02:28'),(109,'home_humantech_organizations','HeartPulse','Clinics',NULL,NULL,NULL,NULL,NULL,0,1,1,'2026-10-14 06:02:28','2026-10-14 06:02:28'),(110,'h