INSERT INTO `job_postings` (`id`, `title`, `slug`, `category`, `location`, `job_type`, `shift`, `pay`, `summary`, `description`, `requirements`, `benefits`, `status`, `featured`, `created_at`, `updated_at`) VALUES (1,'Registered Nurse — Med/Surg','registered-nurse-medsurg','Nursing','Louisville, KY','Travel','Nights, 3x12','$2,100–$2,400/week','Join a respected med/surg unit on a 13-week travel assignment with weekly pay and benefits.','<p>We\'re seeking an experienced Med/Surg Registered Nurse for a 13-week travel assignment with a respected hospital partner.</p><p>You\'ll deliver patient-centered care on a busy medical-surgical unit, working closely with an established care team.</p>','[\"Active RN license (compact or state-specific)\", \"BLS certification\", \"1+ year recent Med/Surg experience\", \"ACLS preferred\"]','[\"Weekly pay\", \"Travel & housing stipend\", \"Medical, dental & vision\", \"Dedicated recruiter support\"]','open',1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(2,'ICU Registered Nurse','icu-registered-nurse','Nursing','Lexington, KY','Contract','Days, 3x12','$2,300–$2,600/week','Critical care RN needed for a high-acuity ICU with a supportive, experienced team.','<p>Deliver advanced critical care to a diverse ICU patient population. Precepting and a thorough unit orientation provided.</p>','[\"Active RN license\", \"BLS & ACLS required\", \"2+ years ICU experience\", \"Ventilator & titratable drip experience\"]','[\"Competitive weekly pay\", \"Housing assistance\", \"Health insurance from day one\", \"24/7 recruiter support\"]','open',1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(3,'CT Technologist','ct-technologist','Imaging','Indianapolis, IN','Temp-to-hire','Variable','$42–$48/hr','CT Technologist for a growing imaging department, with a clear path to a permanent role.','<p>Perform CT imaging studies, ensure patient safety and image quality, and collaborate with radiologists and referring physicians.</p>','[\"ARRT(R)(CT) certification\", \"State licensure where required\", \"1+ year CT experience\"]','[\"Competitive hourly pay\", \"Path to permanent hire\", \"Flexible scheduling\"]','open',0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(4,'Physician Assistant — Family Medicine','physician-assistant-family-medicine','Physician / PA','Cincinnati, OH','Permanent','Monday–Friday','Competitive, based on experience','Permanent placement for a Physician Assistant in a well-established family medicine practice.','<p>Provide comprehensive primary care services to patients of all ages in an outpatient clinic setting.</p>','[\"NCCPA certification\", \"Active state PA license\", \"DEA registration\", \"Family medicine experience preferred\"]','[\"Competitive salary\", \"Health & retirement benefits\", \"Relocation assistance considered\"]','open',0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(5,'Clinical Laboratory Scientist','clinical-laboratory-scientist','Laboratory','Nashville, TN','Contract','Evenings','$38–$44/hr','CLS needed to support a high-volume hospital laboratory on evening shift.','<p>Perform clinical laboratory testing across hematology, chemistry and microbiology sections, ensuring accurate and timely results.</p>','[\"ASCP or equivalent certification\", \"Bachelor\'s degree in medical technology or related field\", \"Hospital lab experience preferred\"]','[\"Shift differential\", \"Weekly pay\", \"Supportive lab leadership team\"]','open',0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(6,'Interim Nurse Manager — Emergency Department','interim-nurse-manager-emergency-department','Nursing Leadership','Columbus, OH','Interim leadership','Days','Competitive, based on experience','Experienced nurse leader needed to steady a busy ED through a leadership transition.','<p>Provide interim leadership for a high-volume emergency department, supporting staff, throughput and quality initiatives during a management transition.</p>','[\"Active RN license\", \"3+ years ED leadership experience\", \"BSN required, MSN preferred\"]','[\"Premium pay\", \"Travel support\", \"Executive-level recruiter support\"]','open',1,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(7,'Health Information Management Specialist','health-information-management-specialist','Healthcare IT','Remote (USA)','Full-time','Business hours','$28–$34/hr','Support medical records accuracy and compliance for a multi-site healthcare system.','<p>Manage health information workflows including chart audits, release of information and EHR data integrity.</p>','[\"RHIT or RHIA preferred\", \"EHR system experience (Epic/Cerner)\", \"Knowledge of HIPAA regulations\"]','[\"Remote flexibility\", \"Full benefits package\", \"Growth opportunities\"]','open',0,'2026-10-13 16:04:46','2026-10-13 16:04:46'),(8,'Front Desk Associate — Clinic','front-desk-associate-clinic','Clerical & Administrative','Louisville, KY','Part-time','Days','$17–$20/hr','Welcoming front desk associate for a busy outpatient clinic.','<p>Greet patients, manage scheduling, verify insurance and support day-to-day front office operations.</p>','[\"Customer service experience\", \"Familiarity with EHR scheduling systems a plus\", \"Strong communication skills\"]','[\"Flexible part-time schedule\", \"On-the-job training\", \"Friendly clinic environment\"]','closed',0,'2026-10-13 16:04:46','2026-10-13 16:04:46');
/*!40000 ALTER TABLE `job_postings` ENABLE KEYS */;
UNLOCK TABLES;

